call_duplicate_move_arg.source:
#![feature(custom_mir, core_intrinsics)]
#![allow(internal_features)]
use core::intrinsics::mir::*;
fn sink(_x: u32, _y: u32) -> u32 { 0 }

#[custom_mir(dialect = "runtime", phase = "post-cleanup")]
pub fn call_dup_move(mut x: u32) -> u32 {
    mir! {
        {
            Call(RET = sink(Move(x), Move(x)), ReturnTo(bb1), UnwindContinue())
        }
        bb1 = { Return() }
    }
}

